"use strict";

// This package's require is satisfied by its OWN private nested copy of
// vt2-vuln-lib, not by the top-level install. Both are 1.0.0 and both
// export `dangerousOp`; only the install PATH tells them apart.
const dep = require("vt2-vuln-lib");

// A private decoy declared FIRST, published by nothing, whose only tie to
// the advisory is its spelling (RWF-011). Nothing calls it.
function dangerousOp(input) {
  return "local decoy, not the dependency's export: " + input;
}

// The one call that matters. It is not in a branch, not behind a flag, and
// not in any export position -- it is the body of the function the class's
// computed key invokes.
function register() {
  dep.dangerousOp("from-computed-key");
  return "handle";
}

// A harmless local callable, so that key evaluation ORDER is exercised
// rather than assumed.
function tag() {
  return "tag";
}

// THE SCENARIO. `Registry` is a class DECLARATION at module scope, so
// ClassDefinitionEvaluation runs when this module is evaluated, and it
// evaluates each element's computed property name in declaration order --
// the key has to exist before the element can be installed on the
// prototype. `register()` therefore runs on EVERY load of this package,
// and it calls the nested install's `dangerousOp`.
//
// Nothing about this module's EXPORTS is ambiguous. There is exactly one
// `module.exports` write, it is unconditional, it is the last statement in
// the file, and it publishes a function that never touches `dep`. Every
// export-authority family from RWF-014 through RWF-022 inspects this file
// and correctly finds nothing to withdraw. That is deliberate: it isolates
// the question to whether the analyzer believes a computed key is executed
// code at all.
//
// The method BODY is deferred -- it runs only if someone calls the method,
// and nothing does. Only the KEY runs.
class Registry {
  [tag()] = 1;
  [register()]() {
    return dep.dangerousOp("from-method-body");
  }
}

// ------------------------------------------------------------------
// Wrong answers on offer. None of these executes during module
// evaluation, and an analyzer that roots any of them reports AFFECTED for
// a reason the language does not support.
// ------------------------------------------------------------------

// 1. The IDENTICAL computed key on a class inside a function that is never
//    called at module scope. Deferred until `configure()` runs, which it
//    never does. `configure` also declares a same-name `register` shadow
//    that real lexical scoping never resolves the module-scope call to.
function configure() {
  function register() {
    return "shadow";
  }
  class Deferred {
    [register()]() {}
  }
  return Deferred;
}

// 2. A nested class held by an INSTANCE FIELD. The enclosing class IS being
//    defined at module load, so a rule that stopped at "the class is at
//    module scope" roots this key and manufactures a false AFFECTED. The
//    field's VALUE is per-instance, so `Inner` is never defined here.
class Holder {
  inner = class Inner {
    [register()]() {}
  };
}

// 3. The same call in a METHOD BODY under a class that IS defined at module
//    load. Definition-time is the KEY, never the body.
class Probe {
  lazy() {
    return dep.dangerousOp("from-probe-body");
  }
}

// 4. A class inside an arrow that nothing invokes.
const build = () => {
  class InsideArrow {
    [register()]() {}
  }
  return InsideArrow;
};

// The module's whole value: an ordinary function that never reaches `dep`.
// Reaching the sink does not require calling it.
module.exports = function initLib(input) {
  return "safe:" + input;
};

module.exports.configure = configure;
module.exports.build = build;
module.exports.Holder = Holder;
module.exports.Probe = Probe;
module.exports.Registry = Registry;
